<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue';
import type { AnalyticsClient, AuditResult, ExportResult, LoadAuditPageResult } from './client';
import { isAccessFailure, problemCode, problemText, utcInput } from './client';
const props = defineProps<{ client: AnalyticsClient; parentSignal: AbortSignal }>();
const end = new Date(); end.setUTCSeconds(0, 0); const from = ref(new Date(end.getTime() - 7 * 86400000).toISOString().slice(0, 16)); const to = ref(end.toISOString().slice(0, 16)); const action = ref(''); const limit = ref(20);
const page = ref<LoadAuditPageResult>(); const detail = ref<AuditResult>(); const exported = ref<ExportResult>(); const message = ref(''); const busy = ref(false); const exportBusy = ref(false); let operation = '';
const lifetime = new AbortController(); let request: AbortController | undefined; let exportRequest: AbortController | undefined;
props.parentSignal.addEventListener('abort', () => { lifetime.abort(); request?.abort(); exportRequest?.abort(); }, { once: true, signal: lifetime.signal });
function clearAudit(): void { request?.abort(); exportRequest?.abort(); busy.value = false; exportBusy.value = false; page.value = undefined; detail.value = undefined; exported.value = undefined; operation = ''; }
async function loadAudit(next = false): Promise<void> { const cursor = next ? page.value?.nextCursor ?? '' : ''; request?.abort(); const current = new AbortController(); request = current; lifetime.signal.addEventListener('abort', () => current.abort(), { once: true, signal: current.signal }); busy.value = true; message.value = ''; detail.value = undefined; page.value = undefined; exported.value = undefined; operation = ''; try { const result = await props.client.LoadAuditPage({ cursor, limit: limit.value, action: action.value || undefined, from: utcInput(from.value), to: utcInput(to.value) }, current.signal); if (!current.signal.aborted) page.value = result; } catch (error) { if (!current.signal.aborted) { clearAudit(); message.value = problemText(error); } } finally { if (request === current && !lifetime.signal.aborted) busy.value = false; } }
async function readAuditDetail(id: string): Promise<void> { request?.abort(); const current = new AbortController(); request = current; lifetime.signal.addEventListener('abort', () => current.abort(), { once: true, signal: current.signal }); busy.value = true; detail.value = undefined; message.value = ''; try { const result = await props.client.ReadAudit(id, current.signal); if (!current.signal.aborted) detail.value = result; } catch (error) { if (!current.signal.aborted) { if (isAccessFailure(error)) clearAudit(); if (problemCode(error) === 'GONE') { exported.value = undefined; operation = ''; } message.value = problemText(error); } } finally { if (request === current && !lifetime.signal.aborted) busy.value = false; } }
async function exportAuditCSV(): Promise<void> { if (exportBusy.value) return; const current = new AbortController(); exportRequest?.abort(); exportRequest = current; lifetime.signal.addEventListener('abort', () => current.abort(), { once: true, signal: current.signal }); exportBusy.value = true; if (!operation) operation = crypto.randomUUID(); try { const value = await props.client.RequestExport({ kind: 'audits', from: utcInput(from.value), to: utcInput(to.value), operationId: operation }, current.signal); if (!current.signal.aborted) exported.value = value; } catch (error) { if (!current.signal.aborted) { if (isAccessFailure(error)) clearAudit(); if (problemCode(error) === 'GONE') { exported.value = undefined; operation = ''; } message.value = problemText(error); } } finally { if (exportRequest === current && !lifetime.signal.aborted) exportBusy.value = false; } }
async function downloadAuditCSV(): Promise<void> { if (!exported.value || exportBusy.value) return; const value = exported.value; const current = new AbortController(); exportRequest?.abort(); exportRequest = current; lifetime.signal.addEventListener('abort', () => current.abort(), { once: true, signal: current.signal }); exportBusy.value = true; try { await props.client.DownloadAuthorizedExport({ exportId: value.exportId, kind: value.kind }, current.signal); } catch (error) { if (!current.signal.aborted) { if (isAccessFailure(error)) clearAudit(); if (problemCode(error) === 'GONE') { exported.value = undefined; operation = ''; } message.value = problemText(error); } } finally { if (exportRequest === current && !lifetime.signal.aborted) exportBusy.value = false; } }
onMounted(() => loadAudit()); onBeforeUnmount(() => { lifetime.abort(); request?.abort(); exportRequest?.abort(); clearAudit(); });
</script>
<template>
  <section class="analytics-panel"><h2>管理审计</h2><p class="muted">仅展示安全结构化事实。链校验失败会明确标记，界面不会重写原记录。默认审计保留180天；晚到的历史事实可能因链顺序保留更久。</p>
    <form class="filters" @submit.prevent="loadAudit(false)"><label>起点（UTC）<input v-model="from" type="datetime-local" required @change="clearAudit"></label><label>终点（UTC，不含）<input v-model="to" type="datetime-local" required @change="clearAudit"></label><label>动作<input v-model="action" placeholder="留空查看全部" @change="clearAudit"></label><label>每页<select v-model="limit" @change="clearAudit"><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label><button :disabled="busy">重新载入</button></form>
    <p v-if="message" role="alert">{{ message }}</p><p v-if="busy" role="status">正在读取安全审计…</p>
    <div class="actions"><button :disabled="exportBusy" @click="exportAuditCSV">按日期导出全部动作CSV</button><button v-if="exported" :disabled="exportBusy" @click="downloadAuditCSV">下载已封存审计CSV</button><small v-if="exported">到期 {{ exported.expiresAt }} · 水位 {{ exported.watermark }}</small></div>
    <template v-if="page"><p v-if="!page.auditIds.length" class="muted">当前条件没有审计记录。</p><ul class="audit-list"><li v-for="id in page.auditIds" :key="id"><button :disabled="busy" @click="readAuditDetail(id)">{{ id }}</button></li></ul><button v-if="page.nextCursor" :disabled="busy" @click="loadAudit(true)">下一页</button></template>
    <article v-if="detail" class="audit-detail"><strong :class="detail.chainValid ? 'valid' : 'invalid'">{{ detail.chainValid ? '本条内容与前驱链校验通过' : '链完整性校验未通过，请联系管理员核查' }}</strong><dl><dt>动作</dt><dd>{{ detail.auditJSON.action }}</dd><dt>原主体</dt><dd>{{ detail.auditJSON.actorId }}</dd><dt>资源</dt><dd>{{ detail.auditJSON.resourceId }}</dd><dt>结果</dt><dd>{{ detail.auditJSON.resultCode }}</dd><dt>发生时间</dt><dd>{{ detail.auditJSON.occurredAt }}</dd></dl><details><summary>安全追溯字段</summary><pre>{{ JSON.stringify(detail.auditJSON, null, 2) }}</pre></details></article>
  </section>
</template>
